#!/usr/bin/env python3
"""EVALUATION ONLY. Writes a temporary catalog.enabled.json that additionally lists the given components / starter projects (with their
pinned `project` descriptor) so they can be vendored and rendered through the production path. The real list is regenerated by classify.py
afterwards; nothing added here is enabled for customers.
   python3 scripts/hyperframes/eval-enable.py --base <real enabled.json> --out src/lib/hyperframes/catalog.enabled.json --components all --examples all"""
import argparse, json, os, re
R = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
ap = argparse.ArgumentParser(); ap.add_argument('--base', required=True); ap.add_argument('--out', required=True); ap.add_argument('--components', default=''); ap.add_argument('--examples', default=''); ap.add_argument('--blocks', default=''); ap.add_argument('--upstream', required=True); a = ap.parse_args()
man = {i['id']: i for i in json.load(open(os.path.join(R, 'src/lib/hyperframes/catalog.manifest.json')))['items']}
en = json.load(open(a.base)); have = {i['id'] for i in en['items']}
def pick(arg, t): return [k for k, v in man.items() if v['type'] == t] if arg == 'all' else [x for x in arg.split(',') if x]
for k in ([x for x in a.blocks.split(',') if x] if a.blocks else []):
    it = man[k]; files = [f for f in it['files'] if f['sha256']]
    if k in have: continue
    en['items'].append({'id': k, 'type': 'block', 'title': it['title'], 'description': it['description'], 'tags': it['tags'], 'category': 'eval', 'dimensions': it['dimensions'], 'duration': it['duration'], 'sourceSha256': it['sourceSha256'], 'readyToUse': False, 'files': [{'path': f['path'], 'target': f['target'], 'sha256': f['sha256']} for f in files], 'editables': []})
for k in pick(a.components, 'component'):
    it = man[k]
    html = open(os.path.join(a.upstream, 'registry/components', k, k + '.html')).read()
    d = re.search(r'data-composition-duration="([\d.]+)"', html) or re.search(r'data-duration="([\d.]+)"', html)
    files = [f for f in it['files'] if f['sha256']]
    en['items'].append({'id': k, 'type': 'component', 'title': it['title'], 'description': it['description'], 'tags': it['tags'], 'category': 'eval', 'dimensions': {'width': 1920, 'height': 1080}, 'duration': float(d.group(1)) if d else 5.0,
        'sourceSha256': it['sourceSha256'], 'readyToUse': False, 'files': [{'path': f['path'], 'target': f['target'], 'sha256': f['sha256']} for f in files], 'editables': [],
        'project': {'dir': 'components', 'host': True, 'files': {f['path']: f['sha256'] for f in files}}})
for k in pick(a.examples, 'example'):
    it = man[k]; files = [f for f in it['files'] if f['sha256']]
    dims = it.get('dimensions') or {'width': 1920, 'height': 1080}
    en['items'].append({'id': k, 'type': 'example', 'title': it['title'], 'description': it['description'], 'tags': it['tags'], 'category': 'eval', 'dimensions': dims, 'duration': it.get('duration') or 10,
        'sourceSha256': next((f['sha256'] for f in files if f['path'] == 'index.html'), ''), 'readyToUse': False, 'files': [{'path': f['path'], 'target': f['target'], 'sha256': f['sha256']} for f in files], 'editables': [],
        'project': {'dir': f'examples/{k}', 'entry': 'index.html', 'files': {f['path']: f['sha256'] for f in files}}})
json.dump(en, open(a.out, 'w'))
print('items', len(en['items']))
